INSERT INTO persons (id, name, birth_year, birth_month, death_year, death_month, roles, bio, links) VALUES ('temujin', '铁木真', 1162, NULL, 1227, NULL, ARRAY['大汗'], '成吉思汗，统一蒙古诸部，1206年建国，开创大蒙古国。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/成吉思汗"}]'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links;
INSERT INTO persons (id, name, birth_year, birth_month, death_year, death_month, roles, bio, links) VALUES ('ogedei', '窝阔台', NULL, NULL, NULL, NULL, ARRAY['大汗'], '蒙古帝国第二任大汗，成吉思汗第三子，灭金、西征欧洲。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/窝阔台"}]'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links;
