INSERT INTO persons (id, name, birth_year, birth_month, death_year, death_month, roles, bio, links) VALUES ('mongke', '蒙哥', NULL, NULL, NULL, NULL, ARRAY['大汗'], '蒙古帝国第四任大汗，拖雷长子，攻宋、灭大理，帝国分裂前最后一位普遍承认的大汗。', '[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/蒙哥"}]'::jsonb) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, birth_year = EXCLUDED.birth_year, birth_month = EXCLUDED.birth_month, death_year = EXCLUDED.death_year, death_month = EXCLUDED.death_month, roles = EXCLUDED.roles, bio = EXCLUDED.bio, links = EXCLUDED.links;
